SELECT Generale.Data, Generale.EsitoComm, Luogo.Descrizione, Tipologia.Descrizione, Genere.Descrizione, Sum(Generale.Qta) AS SommaDiQta, Sum(Generale.Resto) AS SommaDiResto, Sum(Generale.QtaS) AS SommaDiQtaS, Sum(Generale.RestoS) AS SommaDiRestoS, Generale.Rapporo, Sum([qtas]*160+[restos]) AS Tot, [tot]-[CostoRapporto] AS Diff, Sum(IIf([genere].[Descrizione]='Vino' Or [genere].[Descrizione]='Galline',[qta],[qta]*6+[resto])) AS Pesinali, IIf([Genere].[Descrizione]="Vino" Or [Genere].[Descrizione]="Galline",[rapporo]*[Pesinali],[rapporo]/6*[pesinali]) AS CostoRApporto, [EsitoComm] & ' ' & [Tipologia].[Descrizione] & '. ' & [Luogo].[Descrizione] AS Tipo, "" AS Normalizzata INTO NormalizzatiCosti
FROM ((Generale LEFT JOIN Genere ON Generale.IdGenere = Genere.IdGenere) LEFT JOIN Luogo ON Generale.IdLuogo = Luogo.IdLuogo) LEFT JOIN Tipologia ON Generale.IdTipologia = Tipologia.IdTipologia
GROUP BY Generale.Data, Generale.EsitoComm, Luogo.Descrizione, Tipologia.Descrizione, Genere.Descrizione, Generale.Rapporo, ""
HAVING (((Generale.EsitoComm)="rendita") AND (Not (Sum(Generale.QtaS)) Is Null And (Sum(Generale.QtaS))>0)) OR (((Generale.EsitoComm)="rendita") AND (Not (Sum(Generale.RestoS)) Is Null And (Sum(Generale.RestoS))>0));
